import{_ as o,C as r,o as i,c as l,j as a,a as t,E as s,ak as c}from"./chunks/framework.DxrHb2fb.js";const g=JSON.parse('{"title":"阴影与材质","description":"","frontmatter":{},"headers":[],"relativePath":"design/shadow.md","filePath":"design/shadow.md","lastUpdated":1790029076000}'),n={name:"design/shadow.md"};function h(f,e,p,x,m,u){const d=r("XhTokenTable");return i(),l("div",null,[e[0]||(e[0]=a("h1",{id:"阴影与材质",tabindex:"-1"},[t("阴影与材质 "),a("a",{class:"header-anchor",href:"#阴影与材质","aria-label":'Permalink to "阴影与材质"'},"​")],-1)),e[1]||(e[1]=a("p",null,'阴影在这里只表达"离页面多远"，不表达边界——边界归描边。所以阴影只有四个海拔角色，每个角色对应一类离开页面的方式；材质配方把底、边、影、高光与前景打包成四档，组件只挑档，不自己配光。',-1)),e[2]||(e[2]=a("h2",{id:"海拔角色",tabindex:"-1"},[t("海拔角色 "),a("a",{class:"header-anchor",href:"#海拔角色","aria-label":'Permalink to "海拔角色"'},"​")],-1)),s(d,{kind:"shadow",names:["--xh-elevation-raised","--xh-elevation-lifted","--xh-elevation-floating","--xh-elevation-sheet"],notes:{"--xh-elevation-raised":"贴在页面上、略抬起的面：Card、Segmented 与 Tabs 的滑块、静止的滑杆拇指、开关拇指。必带 border-default 描边，影只是加成","--xh-elevation-lifted":"被指针拎起来、正跟着手移动的东西：拖动中的滑杆拇指、排序项、取色器拇指。比 raised 高、没到 floating","--xh-elevation-floating":"portal 出去的锚定浮层里含网格或多列的面板：日期 / 时间选择器面板、NavigationMenu 面板、侧栏弹出层","--xh-elevation-sheet":"模态与强反馈面：Dialog、Drawer、Command、Toast、Notification"}}),e[3]||(e[3]=c('<p>原语只有 <code>--xh-shadow-sm / md / lg / xl</code> 四档；lifted 落在 raised 与 floating 之间，原语里没有它的位置，所以直接写成三层配方。海拔逐部件登记（门禁 <code>check-elevation-role</code>），登记表之外的部件不许消费阴影。</p><h2 id="四档材质" tabindex="-1">四档材质 <a class="header-anchor" href="#四档材质" aria-label="Permalink to &quot;四档材质&quot;">​</a></h2><p>每档提供同名九项令牌：<code>bg</code>、<code>backdrop</code>、<code>border</code>、<code>highlight</code>、<code>shadow</code>、<code>separator</code>、<code>fg</code>、<code>fg-muted</code>、<code>focus-surface</code>。</p><table tabindex="0"><thead><tr><th>档</th><th>令牌</th><th>给谁</th><th>光学</th></tr></thead><tbody><tr><td>M0 solid</td><td><code>--xh-material-solid-*</code></td><td>静态内容面缺省：border-default 描边 + surface 底 + 无影；字段静息同为描边式</td><td>实体底色，无高光、无投影</td></tr><tr><td>M1 soft</td><td><code>--xh-material-soft-*</code></td><td>Button soft、Tag、Popconfirm 动作等次级操作；不用于 Card 与字段</td><td>实体底色，细微顶光与两段接触投影，无背景模糊</td></tr><tr><td>M2 frosted</td><td><code>--xh-material-frosted-*</code></td><td>短列表、菜单、tooltip、气泡等需要透景的锚定瞬态浮层</td><td>0.88 不透明度，16px 模糊，108% 饱和度，1px 可见边界</td></tr><tr><td>M4 elevated</td><td><code>--xh-material-elevated-*</code></td><td>Dialog、Drawer、Command、Tour、Toast、Notification 等模态与强反馈面，必有 1px 描边</td><td>完全不透明，无背景模糊，三层高层投影</td></tr></tbody></table><p>另有两个由海拔组成的叠加档：raised = solid 描边 + solid 底 + <code>--xh-elevation-raised</code>（Card 与可抬起 / 可拖起部件）；floating = solid 底 + <code>--xh-border-default</code> + <code>--xh-elevation-floating</code>（含网格或多列的锚定面板）。它们没有 <code>--xh-material-*</code> 令牌。</p><h2 id="磨砂面的范围" tabindex="-1">磨砂面的范围 <a class="header-anchor" href="#磨砂面的范围" aria-label="Permalink to &quot;磨砂面的范围&quot;">​</a></h2><ul><li>只用于需要保留背景空间感的瞬态浮层；正文、表单主体、Card、Table、Toast 与 Dialog 主阅读面不用。</li><li>含网格或多列的锚定面板（日期面板、多列级联）改用 floating：实体底、不透景，网格线不会与背景打架。</li><li>不把 <code>backdrop-filter</code> 放在页面根、大滚动区或重叠的多层表面，不对模糊半径做动画。</li><li>焦点环必须搭配 <code>focus-surface</code> 对应的实体隔离面。</li><li>没有 glass 材质，也没有任何兼容别名；透明浮层只允许 frosted 这一种柔和模糊。</li></ul><p>Tooltip 等小型反白面用三支 compact 配方（<code>--xh-material-frosted-compact-alpha / -backdrop / -shadow</code>：0.94 不透明度、8px 模糊、明暗独立的小投影）组合 M2 的边界、前景与高光。</p><h2 id="深色档的投影" tabindex="-1">深色档的投影 <a class="header-anchor" href="#深色档的投影" aria-label="Permalink to &quot;深色档的投影&quot;">​</a></h2><p>深色主题的投影色留在纯黑：中性色阶最暗的一档比页面底还亮，拿它当投影压不出深度。四档都在末尾带一条 1px 的浅色描边把面的上沿提出来——raised 与 lifted 那条写成 inset 且只画上边缘，不绕四周，否则会与输入框壳、滑杆拇指自带的描边并成相距 1px 的两道线。</p><h2 id="环境轴上的降级" tabindex="-1">环境轴上的降级 <a class="header-anchor" href="#环境轴上的降级" aria-label="Permalink to &quot;环境轴上的降级&quot;">​</a></h2><p>同一令牌名原位降级：高对比档提高不透明度并加强边界；减少透明度（<code>data-transparency=&quot;reduce&quot;</code>）与打印改为实体底并关闭背景滤镜；强制色改由 <code>Canvas</code> / <code>CanvasText</code> 表达。四档在浅色、深色两套主题下都按黑、白、中灰、页面与品牌背景验证正文至少 4.5:1、焦点环对隔离底至少 3:1。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/design/shape">形状与边界</a> · <a href="/design/dark">暗黑模式</a></li><li>指南：<a href="/guide/theme#材质配方">设计令牌与主题 · 材质配方</a></li></ul>',14))])}const T=o(n,[["render",h]]);export{g as __pageData,T as default};
